/**
 * Validates that an authentication token is a non-empty, cryptographically
 * secure 64-character hexadecimal string generated by the PHP backend.
 * Rejects legacy/insecure placeholder strings like "local-session" or "authenticated".
 */
export function isValidTokenFormat(token: unknown): boolean {
  if (typeof token !== 'string') return false;
  const trimmed = token.trim();
  if (trimmed === 'local-session' || trimmed === 'authenticated') return false;
  return /^[a-f0-9]{64}$/i.test(trimmed);
}

/**
 * Checks whether an expiration timestamp (ISO string or unix ms) has elapsed.
 */
export function isTokenExpired(expiresAt: string | number | Date): boolean {
  const expiryTime = new Date(expiresAt).getTime();
  if (isNaN(expiryTime)) return true;
  return Date.now() >= expiryTime;
}

/**
 * Evaluates a stored session string to ensure it meets strict security criteria.
 */
export function validateSessionToken(token: unknown): {
  isValid: boolean;
  sanitizedToken?: string;
  rejectionReason?: string;
} {
  if (!token || typeof token !== 'string') {
    return { isValid: false, rejectionReason: 'TOKEN_EMPTY' };
  }

  const clean = token.trim();

  if (clean === 'local-session' || clean === 'authenticated') {
    return {
      isValid: false,
      rejectionReason: 'INSECURE_PLACEHOLDER_REJECTED',
    };
  }

  if (!/^[a-f0-9]{64}$/i.test(clean)) {
    return {
      isValid: false,
      rejectionReason: 'INVALID_HEX_FORMAT',
    };
  }

  return {
    isValid: true,
    sanitizedToken: clean.toLowerCase(),
  };
}

/**
 * Formats standardized, user-friendly authentication error messages in Marathi and English.
 */
export function formatAuthError(
  status: number,
  backendMessage?: string,
  lang: 'mr' | 'en' = 'mr'
): string {
  if (status === 429) {
    return lang === 'mr'
      ? 'खूप चुकीचे प्रयत्न झाले आहेत. कृपया १५ मिनिटे प्रतीक्षा करा.'
      : 'Too many failed login attempts. Please wait 15 minutes before trying again.';
  }

  if (status === 401) {
    return lang === 'mr'
      ? 'चुकीचे युजरनेम किंवा पासवर्ड.'
      : 'Invalid username or password.';
  }

  if (backendMessage && backendMessage.trim().length > 0) {
    return backendMessage.trim();
  }

  return lang === 'mr'
    ? 'प्रमाणीकरण त्रुटी: कृपया पुन्हा प्रयत्न करा.'
    : 'Authentication error: Please try again.';
}
